; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpc (Amstrad CPC - direct hardware, no firmware), starts in normal mode
; ============================================================

			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 1		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			jr ntc_start2
ntc_bk_sp:		dw 0			; #0042: main RAM's SP while a bank runs
ntc_bk_out:
			out (c), c		; #0044: BC = the other side's RAM setting
			jp ntc_bk_land		; #0046: main RAM switched in
ntc_bk_land:
			ld sp, (ntc_bk_sp)
			ret				; to where main RAM handed over
			ASSERT ntc_bk_out == #0044, "the bank switch must be at #0044"
ntc_start2:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			di				; (KL ROM SELECT lets interrupts in again)
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld ix, ntc_go
			jp ntc_plat_irqon		; interrupt handler for normal mode
ntc_go:
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_scrinit		; mode 1, ROMs off, clear screen

			; 1: n = 10 : m = -3
			dw kw_ltov, 10, var_n
			dw kw_ltov, -3, var_m

			; 2: FOR i = 1 TO 10 : NEXT
			dw kw_ltov, 1, var_i
for1_t:
			dw kw_next1l_n, var_i, 10, for1_t
for1_e:

			; 3: PRINT "a"; i
			dw kw_printzoscii
			dw glyph_61, 0		; "a"
			dw kw_printint, var_i
			dw kw_printnl

			; 4: FOR i = 1 TO n : s = s + i : NEXT : PRINT "b"; s; i
			dw kw_ltov, 1, var_i
			dw kw_vtov, var_n, for2_l
			dw kw_forupv_n, var_i, for2_l, for2_e
for2_t:
			dw kw_add, var_s, var_i, var_s
			dw kw_next1v_n, var_i, for2_l, for2_t
for2_e:
			dw kw_printzoscii
			dw glyph_62, 0		; "b"
			dw kw_printint, var_s
			dw kw_printint, var_i
			dw kw_printnl

			; 5: FOR i = n TO 1 STEP -1 : PRINT i; : NEXT : PRINT
			dw kw_vtov, var_n, var_i
			dw kw_fordnl_n, var_i, 1, for3_e
for3_t:
			dw kw_printint, var_i
			dw kw_nextdnl_n, var_i, -1, 1, for3_t
for3_e:
			dw kw_printnl

			; 6: FOR i = 1 TO n STEP 3 : PRINT i; : NEXT : PRINT
			dw kw_ltov, 1, var_i
			dw kw_vtov, var_n, for4_l
			dw kw_forupv_n, var_i, for4_l, for4_e
for4_t:
			dw kw_printint, var_i
			dw kw_nextupv_n, var_i, 3, for4_l, for4_t
for4_e:
			dw kw_printnl

			; 7: FOR i = 10 TO m STEP -4 : PRINT i; " "; : NEXT : PRINT
			dw kw_ltov, 10, var_i
			dw kw_vtov, var_m, for5_l
			dw kw_fordnv_n, var_i, for5_l, for5_e
for5_t:
			dw kw_printint, var_i
			dw kw_printzoscii
			dw glyph_20, 0		; " "
			dw kw_nextdnv_n, var_i, -4, for5_l, for5_t
for5_e:
			dw kw_printnl

			; 8: FOR i = 5 TO 1 : PRINT "x" : NEXT : PRINT "c"; i
			dw kw_ltov, 5, var_i
			dw for6_e_go
for6_t:
			dw kw_printzoscii
			dw glyph_78, 1, 0		; "x\n"
			dw kw_next1l_n, var_i, 1, for6_t
for6_e:
			dw kw_printzoscii
			dw glyph_63, 0		; "c"
			dw kw_printint, var_i
			dw kw_printnl

			; 9: FOR i = n TO 1 : PRINT "x" : NEXT : PRINT "d"; i
			dw kw_vtov, var_n, var_i
			dw kw_forupl_n, var_i, 1, for7_e
for7_t:
			dw kw_printzoscii
			dw glyph_78, 1, 0		; "x\n"
			dw kw_next1l_n, var_i, 1, for7_t
for7_e:
			dw kw_printzoscii
			dw glyph_64, 0		; "d"
			dw kw_printint, var_i
			dw kw_printnl

			; 10: FOR i = m TO -1 : PRINT i; : NEXT : PRINT
			dw kw_vtov, var_m, var_i
			dw kw_forupl_n, var_i, -1, for8_e
for8_t:
			dw kw_printint, var_i
			dw kw_next1l_n, var_i, -1, for8_t
for8_e:
			dw kw_printnl

			; 11: FOR i = 254 TO 258 : PRINT i; " "; : NEXT : PRINT
			dw kw_ltov, 254, var_i
for9_t:
			dw kw_printint, var_i
			dw kw_printzoscii
			dw glyph_20, 0		; " "
			dw kw_next1l_n, var_i, 258, for9_t
for9_e:
			dw kw_printnl

			; 12: FOR i = -2 TO 2 : PRINT i; " "; : NEXT : PRINT
			dw kw_ltov, -2, var_i
for10_t:
			dw kw_printint, var_i
			dw kw_printzoscii
			dw glyph_20, 0		; " "
			dw kw_next1l_n, var_i, 2, for10_t
for10_e:
			dw kw_printnl

			; 13: st = 2 : FOR i = 1 TO 6 STEP st : PRINT i; : NEXT : PRINT
			dw kw_ltov, 2, var_st
			dw kw_ltov, 1, var_i
			dw kw_vtov, var_st, for11_s
			dw kw_ltov, 6, for11_l
			dw kw_forentry_n, var_i, for11_s, for11_l, for11_e
for11_t:
			dw kw_printint, var_i
			dw kw_fornext_n, var_i, for11_s, for11_l, for11_t
for11_e:
			dw kw_printnl
			dw kw_stop

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

for6_e_go:			ld sp, for6_e
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_n:			dw 0
var_m:			dw 0
var_i:			dw 0
for2_l:			dw 0
var_s:			dw 0
for4_l:			dw 0
for5_l:			dw 0
var_st:			dw 0
for11_s:			dw 0
for11_l:			dw 0

; ============================================================
; ZOSCII glyphs - each points at its 8 byte bitmap in ntc_font
; ============================================================

glyph_20			equ ntc_font + 0		; " "
glyph_61			equ ntc_font + 520		; "a"
glyph_62			equ ntc_font + 528		; "b"
glyph_63			equ ntc_font + 536		; "c"
glyph_64			equ ntc_font + 544		; "d"
glyph_78			equ ntc_font + 704		; "x"

; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPC (NTCCPC.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_forupl_n:	jp 23
kw_forupv_n:	jp 25
kw_fordnl_n:	jp 27
kw_fordnv_n:	jp 29
kw_next1l_n:	jp 31
kw_next1v_n:	jp 33
kw_nextupv_n:	jp 38
kw_nextdnl_n:	jp 40
kw_nextdnv_n:	jp 42
kw_forentry_n:	jp 44
kw_fornext_n:	jp 46
kw_ltov:		jp 47
kw_vtov:		jp 48
kw_add:		jp 53
kw_printzoscii:	jp 129
kw_printint:	jp 132
kw_printnl:	jp 139
kw_scrinit:	jp 147
ntc_plat_irqon:	jp 308
NTC_RJ_N	equ 21		; entries
ntc_csp	equ #8800		; ROM data
ntc_font	equ #948E		; ROM bss
ntc_nmode	equ #8807		; ROM data
ntc_v_free	equ #88B0		; ROM data
ntc_v_romen	equ #88B6		; ROM data
ntc_v_romold	equ #88B8		; ROM data
ntc_v_stamp	equ #88B4		; ROM data
ntc_v_start	equ #88B2		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)


; the start code (Library: ROM): run once, then the arrays go over it
ntc_rj_drop:
; the start: find the ROM set in slots 0 - 31 (its main ROM, then the others with the same
; stamp), have the main one patch the jump block. NC = ready; C = not there / too old
; (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			xor a
			ld (ntc_rj_want), a
			call ntc_rj_scan		; the main ROM
			jp c, ntc_rj_nf
			ld (ntc_rj_slots), a
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, 1
ntc_rj_more:				; the other ROMs of the set
			ld (ntc_rj_want), a
			ld hl, ntc_rj_n
			cp (hl)
			jr nc, ntc_rj_all
			call ntc_rj_scan
			jp c, ntc_rj_part
			ld b, a
			ld a, (ntc_rj_want)
			ld e, a
			ld d, 0
			ld hl, ntc_rj_slots
			add hl, de
			ld (hl), b
			inc a
			jr ntc_rj_more
ntc_rj_all:
			ld a, (ntc_rj_slots)
			ld c, a
			call #B90F		; KL ROM SELECT: the main ROM
			di					; (KL ROM SELECT lets interrupts in)
			ld a, (ntc_rj_slots)	; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
			ld de, ntc_rj_slots
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot, DE = slots; C: DE = a number it hasn't got
			jp c, ntc_rj_lacks
			IF (ntc_bss >= 32768) && (ntc_bssfrom <= 16384)	; fwdref-ok
			ld hl, ntc_bssfrom		; (the end of the program - or this start code, which tables may go over)
			ELSE
			ld hl, ntc_free
			ENDIF
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, 0
			ld (ntc_v_stamp), hl
			ld a, 0
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
; ntc_rj_scan - a ROM of the set: ROM ntc_rj_want (0 = the main one, any stamp; the others
; with the main one's stamp). NC: A = its slot, HL = past its block's count byte (the main
; one: at its patcher), it is selected. C: not there
ntc_rj_scan:
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; DE = its set's stamp
			inc hl
			ld a, (ntc_rj_want)
			cp (hl)				; its place in the set
			jr nz, ntc_rj_skip
			or a
			jr z, ntc_rj_got
			push hl
			ld hl, (ntc_rj_set)
			or a
			sbc hl, de
			pop hl
			jr nz, ntc_rj_skip		; another build's
ntc_rj_got:
			ld (ntc_rj_set), de
			inc hl
			ld a, (hl)
			ld (ntc_rj_n), a		; ROMs in the set
			inc hl
			ld a, c
			or a				; NC
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			scf					; C: not there
			ret
ntc_rj_nf:
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_part:				; a ROM of the set is missing: its number (1 = the main one)
			ld a, (ntc_rj_want)
			inc a
			ld e, a
			ld d, 0
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tpt
			jr ntc_rj_fnum
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fnum:
			ld a, 1
			ld (ntc_rj_pn), a		; the number after the message
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld a, (ntc_rj_pn)
			or a
			jr z, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
ntc_rj_num:		dw 0
ntc_rj_pn:		db 0			; 1 = a number goes after the message
ntc_rj_want:	db 0			; the ROM of the set looked for
ntc_rj_n:		db 1			; ROMs in the set
ntc_rj_set:		dw 0			; the set's stamp
ntc_rj_slots:	ds 8			; each ROM's slot, the main one first
ntc_rj_sig:		db "NTC", 2, "CPC", 0	; the ROMs' NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "ROM NTC CPC (NTCCPC.ROM) not found", 0
ntc_rj_tlk:		db "ROM NTC CPC too old: no routine #", 0
ntc_rj_tpt:		db "ROM NTCCPC<n>.ROM not found: n = #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0
ntc_rj_dropend:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
			IF ntc_rj_dropend == ntc_end	; fwdref-ok
ntc_bssfrom	equ ntc_rj_drop		; the arrays over the start code (it has run)
			ELSE
ntc_bssfrom	equ ntc_end
			ENDIF
ntc_bss		equ ntc_bssfrom
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
